-- ---------------------------------------------------------------------------
-- updated_at: stamped on every update of a to-do or a request.
-- ---------------------------------------------------------------------------
create or replace function public.backlog_touch_updated_at()
returns trigger
language plpgsql
set search_path = ''
as $fn$
begin
  new.updated_at := pg_catalog.now();
  return new;
end;
$fn$;
--> statement-breakpoint
create trigger admin_todos_touch_updated_at
  before update on public.admin_todos
  for each row execute function public.backlog_touch_updated_at();
--> statement-breakpoint
create trigger feature_requests_touch_updated_at
  before update on public.feature_requests
  for each row execute function public.backlog_touch_updated_at();
--> statement-breakpoint

-- ---------------------------------------------------------------------------
-- RLS (admin:backlog): every operation needs app_role_at_least('admin'), which is
-- false for disabled, pending and rejected users (0004). Policies bind
-- `authenticated` only, so `anon` gets nothing. Server code (postgres /
-- service_role, BYPASSRLS) authorizes with assertCan('admin:backlog') first.
-- ---------------------------------------------------------------------------
alter table public.admin_todos            enable row level security;
--> statement-breakpoint
alter table public.feature_requests       enable row level security;
--> statement-breakpoint
alter table public.feature_request_images enable row level security;
--> statement-breakpoint
revoke truncate, trigger, references on public.admin_todos, public.feature_requests,
  public.feature_request_images from anon, authenticated;
--> statement-breakpoint
create policy admin_todos_admin on public.admin_todos for all to authenticated
  using ((select public.app_role_at_least('admin')))
  with check ((select public.app_role_at_least('admin')));
--> statement-breakpoint
create policy feature_requests_admin on public.feature_requests for all to authenticated
  using ((select public.app_role_at_least('admin')))
  with check ((select public.app_role_at_least('admin')));
--> statement-breakpoint
create policy feature_request_images_admin on public.feature_request_images for all to authenticated
  using ((select public.app_role_at_least('admin')))
  with check ((select public.app_role_at_least('admin')));
--> statement-breakpoint

-- ---------------------------------------------------------------------------
-- Storage: private bucket `admin-attachments` (contracts/schema.md "Storage").
-- Path requests/{request_id}/{image_id}.{ext}; PNG/JPEG/WebP/GIF up to 10 MiB.
-- Select / insert / delete for admins only. Created here, as 0003 does for
-- `resources`, so local and CI stacks match hosted projects; a no-op where the
-- bucket already exists.
-- ---------------------------------------------------------------------------
insert into storage.buckets (id, name, public, file_size_limit, allowed_mime_types)
values ('admin-attachments', 'admin-attachments', false, 10485760,
        array['image/png', 'image/jpeg', 'image/webp', 'image/gif'])
on conflict (id) do nothing;
--> statement-breakpoint
create policy admin_attachments_select on storage.objects for select to authenticated
  using (bucket_id = 'admin-attachments' and (select public.app_role_at_least('admin')));
--> statement-breakpoint
create policy admin_attachments_insert on storage.objects for insert to authenticated
  with check (bucket_id = 'admin-attachments' and (select public.app_role_at_least('admin')));
--> statement-breakpoint
create policy admin_attachments_delete on storage.objects for delete to authenticated
  using (bucket_id = 'admin-attachments' and (select public.app_role_at_least('admin')));
